            continue
        # Identify a diagonal step shared by a pair of cells of this color.
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2-r1, c2-c1
                if dr == 0 or abs(dr) != abs(dc):
                    continue
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                # Extend the line beyond each endpoint.
                r, c = r1, c1
                while 0 <= r-sr < h and 0 <= c-sc < w:
                    r, c = r-sr, c-sc
