    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if not dr or abs(dr) != abs(dc):
                    continue
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                # Extend each end of a diagonal, without overwriting the
                # other colored parts of the marker.
                r, c = r1, c1
                while 0 <= r - sr < h and 0 <= c - sc < w:
                    r, c = r - sr, c - sc
                    if out[r][c] == bg:
                        out[r][c] = color
                r, c = r2, c2
                while 0 <= r + sr < h and 0 <= c + sc < w:
                    r, c = r + sr, c + sc
                    if out[r][c] == bg:
                        out[r][c] = color
    return out
